<script lang="ts">import {calculateDeliveryHealth,governanceStatus,projectGovernance,type DeliveryGovernanceRecord} from '../lib/deliveryGovernance.ts';export let record:DeliveryGovernanceRecord|null=null;$: health=record?calculateDeliveryHealth({executionState:record.execution_state,reviewState:record.review_state,ciState:record.ci_state,evidenceComplete:record.pr_state!=='NOT_AVAILABLE',approvalState:record.approval_state,failureCount:0}):0;$: projection=record?projectGovernance(record):null;</script>
{#if record}<section class="delivery-governance-panel" data-testid="delivery-governance-panel"><div class="section-label"><span>Delivery Governance</span><small>{governanceStatus(record)} · read-only projection</small></div><div class="governance-grid"><div><span>WP</span><strong>{record.work_package_id}</strong></div><div><span>Health</span><strong>{health}/100</strong></div><div><span>Lifecycle</span><strong>{record.lifecycle_state}</strong></div><div><span>Execution</span><strong>{record.execution_state}</strong></div><div><span>Provider</span><strong>{record.provider}</strong></div><div><span>Policy</span><strong>{projection?.execution_policy}</strong></div><div><span>Approval</span><strong>{record.approval_state}</strong></div><div><span>PR / Review / CI</span><strong>{record.pr_state} · {record.review_state} · {record.ci_state}</strong></div><div><span>Remediation / UAT</span><strong>{record.remediation_state} · {record.uat_state}</strong></div></div><div class="boundary"><strong>AICC CAN</strong><span>Prepare Delivery · Recommend Provider · Execute Allowed Tasks · Review · CI · Remediation</span><strong>AICC CANNOT</strong><span>Approve Business Change · Merge PR · Release Production</span></div></section>{/if}
